import json
from transformers import AutoTokenizer

LLAMA = "/root/autodl-tmp/models/LLM-Research/Meta-Llama-3.1-8B-Instruct"
QWEN  = "/root/autodl-tmp/models/Qwen3-8B-ms/Qwen/Qwen3-8B"

scierc_types = ["Generic", "Method", "Material", "Metric", "OtherScientificTerm", "Task"]
docred_types = ["LOC", "MISC", "NUM", "ORG", "PER", "TIME"]

def encode_variants(tok, t):
    rows = []
    for name, txt in [("raw", t), ("space_prefix", " " + t)]:
        ids = tok.encode(txt, add_special_tokens=False)
        rows.append({
            "variant": name,
            "text": txt,
            "ids": ids,
            "first_id": ids[0] if ids else None,
            "first_tok_str": tok.decode([ids[0]]) if ids else None,
            "n_tokens": len(ids),
        })
    return rows

def analyze(tok_path, label, types_list):
    print(f"\n=== {label} | types={types_list} ===")
    tok = AutoTokenizer.from_pretrained(tok_path)
    table = {}
    for t in types_list:
        table[t] = encode_variants(tok, t)
        for row in table[t]:
            print(f"  {t:25s} [{row['variant']:12s}]  first_id={row['first_id']:>6}  first='{row['first_tok_str']}'  ids={row['ids']}  n={row['n_tokens']}")

    # uniqueness per variant
    for variant in ("raw", "space_prefix"):
        firsts = {t: next(r for r in table[t] if r["variant"] == variant)["first_id"] for t in types_list}
        seen = {}
        conflicts = []
        for t, fid in firsts.items():
            if fid in seen:
                conflicts.append((seen[fid], t, fid))
            else:
                seen[fid] = t
        status = "PASS" if not conflicts else "FAIL"
        print(f"  [uniqueness/{variant}] {status}  unique={len(set(firsts.values()))}/{len(types_list)}")
        for a, b, fid in conflicts:
            print(f"    CONFLICT: '{a}' vs '{b}' share first_id={fid}")
    return table

out = {}
out["llama_scierc"] = analyze(LLAMA, "Llama-3.1-8B SciERC", scierc_types)
out["llama_docred"] = analyze(LLAMA, "Llama-3.1-8B DocRED", docred_types)
out["qwen_scierc"]  = analyze(QWEN,  "Qwen3-8B SciERC", scierc_types)
out["qwen_docred"]  = analyze(QWEN,  "Qwen3-8B DocRED", docred_types)

with open("/tmp/w9_tokenizer_results.json", "w") as f:
    json.dump(out, f, indent=2, ensure_ascii=False)
print("\nSaved /tmp/w9_tokenizer_results.json")
EOF
source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python /tmp/w9_tokenizer_check.py
